/* @lc app=leetcode id=4011 lang=kotlin */ class Solution { fun countRatioSubarrays(nums: IntArray, a: Int, b: Int): Int = nums.indices.sumOf { i -> nums.drop(i).fold(Triple(0, 0, 0)) { (x, y, c), v -> (if (v % 2 == 0) x + 1 else x).let { nx -> (if (v % 2 == 0) y else y + 1).let { ny -> Triple(nx, ny, c + (if (ny > 0 && nx.toLong() * b <= ny.toLong() * a) 1 else 0)) } } }.third } }